input.script:
export const meta = {
  name: 'maester-pack-ideas-research',
  description: 'Research existing security baselines/frameworks (Jamf, Okta, AWS, SaaS, STIGs...) that could become Maester packs',
  phases: [
    { title: 'Research', detail: 'one researcher per product category' },
    { title: 'Verify', detail: 'skeptic checks each category\'s claims against primary sources' },
    { title: 'Gaps', detail: 'completeness critic looks for missed frameworks' },
    { title: 'Synthesize', detail: 'rank candidates into tiers' },
  ],
}

const CONTEXT = `Context: Maester (maester.dev) is an open-source PowerShell 7 framework that runs automated security configuration checks, today mainly for Microsoft 365 / Entra / Azure (with CIS M365, CISA SCuBA, ASD Essential Eight suites, plus CIS GitHub). It now supports "Maester Packs": installable bundles of checks for other products, each with a connector that reads the product's config through its API (PowerShell, REST) and tests mapped to a published framework's requirement IDs (a framework catalogue file holds requirement IDs and facts like level/profile, never the copyrighted benchmark text). Packs can also wrap an existing open-source scanner (run the tool, read its output file) — e.g. packs already exist/are planned for: Microsoft Zero Trust Assessment, CISA ScubaGear (M365), CISA ScubaGoggles (Google Workspace), and Google Workspace as the first official pack.
The goal: find EXISTING, well-known, standard security baselines / benchmarks / hardening guides for other products where a Maester pack could implement or wrap the checks. The user explicitly mentioned Jamf as an example (think macOS Security Compliance Project / mSCP, Jamf Compliance Editor, CIS Apple benchmarks, Jamf Pro API).
Today is 2026-11-08. Use WebSearch (load it via ToolSearch "select:WebSearch,WebFetch") and WebFetch to check primary sources: the benchmark publisher's pages (cisecurity.org benchmark list, public.cyber.mil STIG library, cisa.gov SCuBA, vendor docs, GitHub repos). Do not rely on memory for whether a benchmark exists or its current version — verify. Record source URLs.`

const CANDIDATE_SCHEMA = {
  type: 'object',
  properties: {
    candidates: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          product: { type: 'string', description: 'Product/platform, e.g. Jamf Pro / macOS' },
          category: { type: 'string' },
          standards: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                name: { type: 'string' },
                publisher: { type: 'string' },
                latestVersion: { type: 'string', description: 'version and date if known' },
                approxControls: { type: 'string' },
                license: { type: 'string', description: 'free/registration/paid; machine-readable form (OSCAL, XCCDF, YAML, JSON)?' },
                url: { type: 'string' },
              },
              required: ['name', 'publisher', 'url'],
            },
          },
          dataAccess: { type: 'string', description: 'How a connector would read config: API, auth model, PowerShell module or REST; read-only scopes; any blockers (on-device only, agent required, paid tier)' },
          existingTools: { type: 'string', description: 'Open-source scanners that already implement the checks and could be wrapped (name, repo URL, licence, output format)' },
          audienceFit: { type: 'string', description: 'How likely Maester users (M365/Entra admins, MSPs) also run this product' },
          feasibility: { type: 'string', enum: ['high', 'medium', 'low'] },
          effort: { type: 'string', enum: ['small', 'medium', 'large'] },
          packApproach: { type: 'string', description: 'native checks via API, wrap existing tool, import tool output, or hybrid' },
          notes: { type: 'string' },
          sources: { type: 'array', items: { type: 'string' } },
        },
        required: ['product', 'category', 'standards', 'dataAccess', 'feasibility', 'effort', 'packApproach', 'sources'],
      },
    },
  },
  required: ['candidates'],
}

const VERIFIED_SCHEMA = {
  type: 'object',
  properties: {
    candidates: CANDIDATE_SCHEMA.properties.candidates,
    corrections: { type: 'array', items: { type: 'string' }, description: 'What you corrected or removed and why' },
  },
  required: ['candidates', 'corrections'],
}

const CATEGORIES = [
  { key: 'apple-endpoint', prompt: 'Apple device management and macOS/iOS hardening: Jamf Pro / Jamf School / Jamf Protect, Kandji (Iru), Mosyle, Addigy, Intune for macOS, Apple Business Manager. Standards: NIST macOS Security Compliance Project (mSCP) baselines (800-53, CIS Level 1/2, CMMC, DISA STIG, Indigo, 800-171), Jamf Compliance Editor, CIS Apple macOS/iOS/iPadOS benchmarks, DISA Apple STIGs, Jamf\'s own CIS benchmark support. Also checks of the MDM tenant itself (Jamf Pro admin settings, SSO, API roles) vs device posture reported via MDM inventory/compliance APIs.' },
  { key: 'identity', prompt: 'Identity providers and access: Okta (CISA SCuBA? DISA Okta IDaaS STIG, Okta Secure Identity Commitment / ISPM, CIS?), Ping Identity, Cisco Duo, Auth0, OneLogin, JumpCloud, CyberArk, 1Password/Bitwarden business, Keeper, BeyondTrust, Active Directory (PingCastle, Purple Knight, CIS Windows Server DC). Find official/benchmark baselines for each and their admin APIs.' },
  { key: 'cloud-infra', prompt: 'Public cloud and infrastructure: AWS (CIS AWS Foundations, AWS Foundational Security Best Practices, CIS AWS Compute), Google Cloud (CIS GCP Foundations), Oracle Cloud, Azure beyond M365 (CIS Microsoft Azure Foundations, Microsoft Cloud Security Benchmark), Kubernetes/AKS/EKS/GKE (CIS Kubernetes), Docker, VMware vSphere/ESXi (vSphere Security Configuration Guide, STIG), Cloudflare, HashiCorp Vault/Terraform Cloud. Note which Maester-style API-based checks would make sense vs which are already well served by tools like Prowler, ScoutSuite, Steampipe/Powerpipe, Kubescape, kube-bench, Checkov.' },
  { key: 'saas-collab', prompt: 'SaaS collaboration and business apps (SSPM space): Google Workspace (CIS Google Workspace Foundations, CISA SCuBA GWS), Slack (CIS Slack benchmark?), Zoom (CIS Zoom? DISA Zoom STIG), Salesforce (Salesforce Security Health Check baseline, CIS Salesforce?), ServiceNow, Atlassian Cloud (Jira/Confluence, CIS Atlassian?), Box, Dropbox, Workday, HubSpot, Snowflake (CIS Snowflake Foundations), Databricks (CIS Databricks?), Webex, DocuSign, Adobe. Verify on cisecurity.org which SaaS benchmarks actually exist.' },
  { key: 'devops', prompt: 'DevOps and developer platforms: GitHub (CIS GitHub benchmark is already in Maester - note but focus elsewhere), GitLab (CIS GitLab benchmark?), Bitbucket, Azure DevOps (already partly in Maester), CIS Software Supply Chain Security Guide, OpenSSF Scorecard, SLSA, Legitify (Legit Security), Chain-bench (Aqua), Allstar, Jenkins, Terraform Cloud, npm/PyPI org settings, Atlassian Bamboo. Find benchmarks and open-source scanners whose output could be wrapped.' },
  { key: 'endpoint-network', prompt: 'Endpoint security, Windows/Linux hardening, network/SASE: Microsoft Security Baselines (Windows, Edge, M365 Apps via Security Compliance Toolkit) and Intune security baselines, CIS Microsoft Intune for Windows benchmark, CIS Windows 11 / Server, DISA STIGs for Windows, CrowdStrike Falcon, SentinelOne, Sophos, Defender for Endpoint, Zscaler (ZIA/ZPA - any baseline? CIS?), Netskope, Palo Alto (CIS PAN-OS, Prisma Access), Fortinet (CIS FortiGate), Cisco (CIS IOS), Cloudflare Zero Trust, Tailscale. Focus on items reachable through a cloud management API (Maester runs remotely, not on endpoints), e.g. Intune policy contents vs baseline, CrowdStrike prevention policy vs vendor recommended settings.' },
  { key: 'gov-frameworks', prompt: 'Government and compliance frameworks that could become a pack mapping existing Maester checks (or a new suite) rather than a new product: DISA STIGs for cloud SaaS (Microsoft 365 / Entra / Intune / Defender / Exchange Online / SharePoint Online / Teams STIGs, Okta, Zoom, Google), NIST SP 800-53 / 800-171 / CSF 2.0 (OSCAL catalogs), CMMC 2.0, FedRAMP, ISO 27001:2022 Annex A, SOC 2, PCI DSS 4.0, HIPAA, UK NCSC Cyber Assessment Framework and Cyber Essentials, NCSC cloud security principles, Canada CCCS (ITSG-33, Cloud guardrails / GC Guardrails), New Zealand NZISM, Germany BSI IT-Grundschutz and BSI C5, Spain ENS, Netherlands BIO, EU NIS2 / DORA, Microsoft Cloud Security Benchmark, Microsoft Secure Score, CIS Controls v8.1, CIS Microsoft 365 Benchmark levels (already), Japan ISMAP, Singapore CSA. Prefer ones with machine-readable catalogs (OSCAL, XCCDF) and existing crosswalks to CIS/NIST.' },
]

const results = await pipeline(
  CATEGORIES,
  c => agent(`${CONTEXT}\n\nYour category: ${c.prompt}\n\nResearch this category thoroughly. For each product (or framework) that has a real, published, well-known baseline, return a candidate with the standards (exact name, publisher, latest version/date, size, licence/machine-readable format, URL), how a remote connector would read the config, existing open-source tools that already implement checks, audience fit for Maester's M365/MSP users, feasibility, effort and the best pack approach. Include products that lack a formal benchmark only if the vendor publishes an authoritative hardening guide; say so. Aim for completeness within the category.`, { label: `research:${c.key}`, phase: 'Research', schema: CANDIDATE_SCHEMA }),
  (r, c) => r ? agent(`${CONTEXT}\n\nYou are a skeptical fact-checker. Another researcher produced these pack candidates for category "${c.key}":\n\n${JSON.stringify(r.candidates, null, 1)}\n\nVerify every factual claim against primary sources with WebSearch/WebFetch: does each benchmark/STIG/baseline really exist under that name, what is its latest version and date, is it free, is there a machine-readable form, does the API/PowerShell module exist and expose the needed settings, do the named open-source tools exist and are they maintained (last release/commit)? Fix wrong facts, remove candidates whose standard does not exist (list them in corrections), downgrade feasibility where data access is blocked (e.g. requires an on-device agent, paid tier, no API). Also add any important candidate in this category the researcher missed. Return the corrected list.`, { label: `verify:${c.key}`, phase: 'Verify', schema: VERIFIED_SCHEMA }) : null,
)

const verified = results.filter(Boolean)
const all = verified.flatMap(v => v.candidates)
const corrections = verified.flatMap(v => v.corrections)
log(`${all.length} verified candidates, ${corrections.length} corrections`)

phase('Gaps')
const gaps = await agent(`${CONTEXT}\n\nHere is the verified list of product names researched so far:\n${all.map(c => `- ${c.product} (${c.category}): ${c.standards.map(s => s.name).join('; ')}`).join('\n')}\n\nAct as a completeness critic. What well-known products with an existing published security baseline (CIS benchmark, DISA STIG, CISA SCuBA, vendor hardening guide, NIST mSCP, etc.) are missing that Maester's audience (M365 admins, MSPs, security teams in mid-size orgs) would plausibly run? Check cisecurity.org's full benchmark list and the DISA STIG library for SaaS/cloud entries. Research and verify each addition with primary sources and return them as candidates (only genuinely missing ones).`, { label: 'completeness-critic', phase: 'Gaps', schema: CANDIDATE_SCHEMA })
const allCandidates = all.concat(gaps ? gaps.candidates : [])

phase('Synthesize')
const report = await agent(`${CONTEXT}\n\nHere are all verified pack candidates (JSON):\n${JSON.stringify(allCandidates)}\n\nFact-check corrections made along the way:\n${corrections.join('\n')}\n\nWrite a Markdown research report for Maester's maintainer deciding which packs to build. Structure:\n1. Executive summary (5-8 bullets: the top picks and why).\n2. Ranked shortlist table: rank, pack idea, standard(s) it implements, data access, approach (native/wrap/import), audience fit, effort. Rank by (audience overlap with M365 admins/MSPs) x (strength and freeness of the standard) x (API feasibility).\n3. Tiered sections: Tier 1 build next, Tier 2 good community/partner packs, Tier 3 frameworks-only packs (mapping existing checks to a new framework such as DISA M365 STIGs, NIST 800-53, CMMC, NCSC CAF), Tier 4 not worth it / blocked (and why).\n4. For Jamf specifically: a detailed section (mSCP, Jamf Compliance Editor, CIS macOS, Jamf Pro API, what a pack would check at tenant level vs device fleet compliance level).\n5. Wrap-a-tool opportunities: open-source scanners whose output a pack could import, with licence notes.\n6. Licensing cautions (CIS benchmark text copyright, STIG public domain, etc.).\n7. Sources (deduplicated URLs).\nBe concrete and factual; keep claims tied to sources; note uncertainty where verification was weak.`, { label: 'synthesize', phase: 'Synthesize' })

return { report, candidateCount: allCandidates.length, corrections }

result.output:
